# Initialize an empty grocery list
grocery_list = []

def add_item():
    """Add an item to the grocery list."""
    item = input("Enter an item to add to the grocery list: ").strip()
    grocery_list.append(item)
    print(f"Grocery list: [{', '.join(grocery_list)}]")

def remove_item():
    """Remove an item from the grocery list."""
    if grocery_list:
        item_index = int(input("Enter the index of the item to remove (0-based): "))
        grocery_list.pop(item_index)
        print(f"Grocery list: [{', '.join(grocery_list)}]")
    else:
        print("The grocery list is empty.")

def main():
    while True:
        print("1. Add an item")
        print("2. Remove an item")
        print("3. Display the grocery list")
        print("4. Exit")

        choice = int(input("Enter your choice: "))

        if choice == 1:
            add_item()
        elif choice == 2:
            remove_item()
        elif choice == 3:
            print(f"Grocery list: [{', '.join(grocery_list)}]")
        elif choice == 4:
            print("Goodbye!")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

This program allows users to add items to the grocery list, remove items from the list, and display the list. The user can also exit the program at any time.
